    #include <iostream>
using namespace std;

class Node
{
  public:
    int data;
    Node *next;

    Node(int x)
    {
        data = x;
        next = nullptr;
    }
};

Node *removeDuplicates(Node *head)
{

    // Return if the linked list is empty.
    if (!head)
        return nullptr;

    // Using an unordered_set to keep track of seen values.
    unordered_set<int> seen;
    Node *curr = head;
    Node *prev = nullptr;

    // Iterating through the linked list.
    while (curr != nullptr)
    {

        // If the current value is a duplicate, remove the node.
        if (seen.find(curr->data) != seen.end())
        {
            prev->next = curr->next;
            delete curr;
        }
        else
        {

            // If the value is not a duplicate, add it to the set and update the
            // pointers.
            seen.insert(curr->data);
            prev = curr;
        }
        curr = prev->next;
    }
    return head;
}

